payload:
$ErrorActionPreference='Continue'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
Set-Location $repo
git fetch origin --prune
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }

$tempWt='C:\Users\Xxkan\AppData\Local\Temp\mhw-main-converge-opui-a3'
$tempBranch='reconcile/chatgpt-opui-a3-20260929'
if(Test-Path $tempWt){ git worktree remove --force $tempWt }
git show-ref --verify --quiet "refs/heads/$tempBranch"
if($LASTEXITCODE -eq 0){ git branch -D $tempBranch | Out-Null }

$active=@()
foreach($line in @(git worktree list --porcelain)){
  if($line -like 'branch refs/heads/*'){ $active += $line.Substring(18) }
}
$deleted=@(); $skipped=@()

$session='agent/heaven-bridge-session-recovery-20260929'
git show-ref --verify --quiet "refs/remotes/origin/$session"
if($LASTEXITCODE -eq 0){
  if($session -in $active){ $skipped += [ordered]@{branch=$session;reason='active-worktree'} }
  else {
    git merge-base --is-ancestor "origin/$session" origin/heaven-bridge
    if($LASTEXITCODE -ne 0){ throw 'session recovery branch is no longer subsumed by heaven-bridge' }
    git push origin --delete $session
    if($LASTEXITCODE -eq 0){ $deleted += [ordered]@{branch=$session;proof='ancestor-of-live-heaven-bridge'} } else { throw 'failed deleting session recovery branch' }
  }
}

$required=@(
 'tools/agent-control/README.md',
 'tools/agent-control/agentctl.mjs',
 'tools/agent-control/lib/federated-registry.mjs',
 'tools/agent-control/package.json',
 'tools/agent-control/public/index.html',
 'tools/agent-control/test/federation-dashboard.test.mjs',
 'tools/agent-control/test/operator-ui-cli.test.mjs'
)
foreach($p in $required){
  git cat-file -e "origin/main:$($p)"
  if($LASTEXITCODE -ne 0){ throw "canonical operator UI file missing from main: $p" }
}
$superseded=@(
 'agent/operator-ui-cli-20260929',
 'agent/operator-ui-cli-final-20260929',
 'reconcile/operator-ui-cli-main-20260929',
 'reconcile/operator-ui-cli-main-v2-20260929',
 'integration/agent-control-dashboard-contract-20260929',
 'integration/agent-control-dashboard-contract-final-20260929'
)
foreach($b in $superseded){
  git show-ref --verify --quiet "refs/remotes/origin/$b"
  if($LASTEXITCODE -ne 0){ continue }
  if($b -in $active){ $skipped += [ordered]@{branch=$b;reason='active-worktree'}; continue }
  git push origin --delete $b
  if($LASTEXITCODE -eq 0){ $deleted += [ordered]@{branch=$b;proof='superseded-by-verified-main-operator-ui'} } else { $skipped += [ordered]@{branch=$b;reason='delete-failed'} }
}
git fetch origin --prune | Out-Null
[ordered]@{main=(git rev-parse origin/main);deleted=$deleted;skipped=$skipped;active_worktrees=$active} | ConvertTo-Json -Depth 5
